import { Locator, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const TAG = '#358c8d · #6a993d68bfba343d96358c8d';
const URL = '/settings/business';
const ALERT = 'rgb(233, 150, 127)'; // --nd-alert #E9967F
const ROLE = process.env.QA_358C8D_ROLE || 'business';

/** Обрывает любые записи настроек; возвращает счётчик попыток. */
async function blockWrites(page: Page) {
  const writes: string[] = [];
  await page.route('**/rest/v1/**', (route) => {
    const r = route.request();
    const u = r.url();
    const write =
      ['PATCH', 'PUT', 'DELETE'].includes(r.method()) ||
      (r.method() === 'POST' && (u.includes('/rest/v1/businesses') || /\/rpc\/[^?]*(legal|settings|update|save)/i.test(u)));
    if (!write) return route.continue();
    writes.push(`${r.method()} ${u.slice(0, 120)}`);
    return route.abort();
  });
  return writes;
}

const legalField = (page: Page) => page.locator('textarea#settings-candidate_legal_text, form textarea').first();

/** Цвета значка рядом с текстом: <img src=svg> (цвета из файла) или встроенный <svg> (computed stroke/fill). */
async function iconColors(page: Page, text: Locator): Promise<string[]> {
  const info = await text.evaluate((el) => {
    const host = el.closest('p, div, li, span') ?? el;
    const scope = host.querySelector('img, svg') ? host : host.parentElement ?? host;
    const img = scope.querySelector('img') as HTMLImageElement | null;
    if (img) return { src: img.currentSrc || img.src, colors: [] as string[] };
    const svg = scope.querySelector('svg');
    if (!svg) return { src: null, colors: [] as string[] };
    const colors = [...svg.querySelectorAll('*')].flatMap((n) => {
      const cs = getComputedStyle(n);
      return [cs.stroke, cs.fill].filter((c) => c && c !== 'none' && c !== 'rgba(0, 0, 0, 0)');
    });
    return { src: null, colors };
  });
  expect(info.src || info.colors.length, 'рядом с текстом нет значка').toBeTruthy();
  if (!info.src) return info.colors;
  if (info.src.startsWith('data:')) {
    const svg = decodeURIComponent(info.src.split(',')[1] ?? '');
    return (svg.match(/(?:stroke|fill)="(#[0-9a-fA-F]{3,6})"/g) ?? []).map((s) => s.replace(/.*"(#.*)"/, '$1').toUpperCase());
  }
  const body = await (await page.request.get(info.src)).text();
  return (body.match(/(?:stroke|fill)="(#[0-9a-fA-F]{3,6})"/g) ?? []).map((s) => s.replace(/.*"(#.*)"/, '$1').toUpperCase());
}

const isColor = (c: string, hex: string, rgb: string) => c.toUpperCase() === hex || c.replace(/\s/g, '') === rgb.replace(/\s/g, '');

test.describe(`Настройки бизнеса — נוסח משפטי: цвета предупреждения и ошибок (${TAG})`, () => {
  test(`без נוסח: «עדיין לא נשמר נוסח משפטי…» цветом #E9967F, значок «!» белый #FFFFFF @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser(ROLE);
    await page.setViewportSize({ width: 1440, height: 900 });
    await blockWrites(page);
    await page.goto(URL);
    await expect(legalField(page)).toBeVisible();
    const current = await legalField(page).inputValue();
    test.skip(current.trim() !== '', `у бизнеса роли «${ROLE}» нוסח уже сохранён — нужен слот бизнеса без נוסח (QA_358C8D_ROLE)`);

    // Источник: реджект 21.10 / Figma 869:10340 — текст --nd-alert #E9967F, значок text/primary #FFFFFF.
    const hint = page.getByText(/^עדיין לא נשמר נוסח משפטי/);
    await expect(hint).toBeVisible();
    await expect(hint).toHaveCSS('color', ALERT);
    const colors = await iconColors(page, hint);
    expect(colors.length).toBeGreaterThan(0);
    for (const c of colors) expect(isColor(c, '#FFFFFF', 'rgb(255, 255, 255)') || isColor(c, '#FFF', 'rgb(255, 255, 255)'), `цвет значка ${c}`).toBe(true);
  });

  test(`регресс: пустое «תפקיד איש הקשר» → ошибка у поля коралловая #E9967F со значком #E9967F, запись не уходит @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser('business');
    await page.setViewportSize({ width: 1440, height: 900 });
    const writes = await blockWrites(page);
    await page.goto(URL);
    const role = page.getByLabel(/^תפקיד איש הקשר/);
    await expect(role).toBeVisible();
    await role.fill('');
    await page.getByRole('button', { name: 'שמירת שינויים' }).click();

    // Источник: ответ программиста 02.11 «ошибки полей остаются коралловыми»; факт 04.11.
    const error = page.getByText('יש להזין את תפקיד איש הקשר', { exact: true });
    await expect(error).toBeVisible();
    await expect(error).toHaveCSS('color', ALERT);
    const colors = await iconColors(page, error);
    expect(colors.length).toBeGreaterThan(0);
    for (const c of colors) expect(isColor(c, '#E9967F', ALERT), `цвет значка ошибки ${c}`).toBe(true);
    expect(writes, 'сохранение ушло на сервер').toEqual([]);
  });

  test(`регресс: נוסח 3001 знак → «הנוסח ארוך מדי», сохранение не проходит @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser('business');
    await page.setViewportSize({ width: 1440, height: 900 });
    const writes = await blockWrites(page);
    await page.goto(URL);
    const legal = legalField(page);
    await expect(legal).toBeVisible();
    const before = await legal.inputValue();

    await legal.fill(`QA-AUTO-358c8d ${'א'.repeat(3001)}`.slice(0, 3001));
    await expect(page.getByText(/3[,.]?001\s*\/\s*3[,.]?000/)).toBeVisible();
    await page.getByRole('button', { name: 'שמירת שינויים' }).click();

    // Источник: лимит 3000 (S-06, проверка 21.10 и 04.11). Цвет ошибки длины не проверяется (находка #FFB4AB).
    await expect(page.getByText(/הנוסח ארוך מדי/).first()).toBeVisible();
    expect(writes, 'текст длиннее 3000 отправлен на сервер').toEqual([]);

    // После перезагрузки — прежний текст.
    await page.reload();
    await expect(legalField(page)).toHaveValue(before);
  });

  test(`регресс: מנהל/ת מגייס/ת (user) → /settings/business — отказ «403», формы и נוסח нет @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser('user');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(URL);
    // Источник: S-06 AC5 / D-26 «מסך ההגדרות פתוח למנהל חשבון בלבד»; факт 04.11 «user → 403».
    const denied = page.getByTestId('access-denied');
    await expect(denied).toBeVisible();
    await expect(denied).toContainText('403');
    await expect(denied.getByRole('heading', { name: 'אין לכם גישה לעמוד הזה' })).toBeVisible();
    await expect(page.locator('textarea')).toHaveCount(0);
    await expect(page.getByText(/נוסח משפטי/)).toHaveCount(0);
  });
});
